"""各课独立反例：(标题, 场景, 错误片段, 修改片段, 原因, 三步状态)。

状态中的卡片展示具体变量或数据；第二步标识错误发生，第三步展示正确结果。
代码片段用于对照本课完整程序，而非独立程序。
"""
def case(title, scenario, wrong, right, reason, start, bad, good):
    return (title, scenario, wrong, right, reason, [
        {'cells':start, 'active':[], 'text':'初始状态：'+scenario},
        {'cells':bad, 'active':list(range(len(bad))), 'text':'出错了：'+reason, 'warning':True},
        {'cells':good, 'active':list(range(len(good))), 'text':'修正后：'+title+'，请对照卡片中的结果。'},
    ])

