def graph_case(lesson, index, nodes, edges, chosen, directed=False):
    """为图论反例附上同一张图，每步高亮正在讨论的实际边。"""
    diagram = {'nodes': nodes, 'edges': edges, 'directed': directed}
    for frame, selected in zip(SCENARIOS[lesson][index][5], chosen):
        frame['network'] = diagram
        frame['chosenEdges'] = selected

