def array_visual(lesson,index,states):
    """状态为 (实际数组, 高亮下标, 指针)，保留对应帧的解释和警告。"""
    for frame,(values,active,pointers) in zip(SCENARIOS[lesson][index][5],states):
        frame.update(cells=[str(v) for v in values], indexed=True, active=active, pointers=pointers)

