def matrix_visual(lesson,index,states,rows,cols,active=None):
    for i,(frame,matrix) in enumerate(zip(SCENARIOS[lesson][index][5],states)):
        frame.update(matrix=matrix,rowLabels=rows,colLabels=cols)
        if active and active[i] is not None:frame['matrixActive']=active[i]

